pous.declaration:
FUNCTION_BLOCK TrafficLight
VAR_OUTPUT
    NS_Green : BOOL;
    EW_Green : BOOL;
END_VAR
VAR
    phase : INT := 0;
    timer : TON;
END_VAR

pous.implementation:
IF phase = 0 THEN
    NS_Green := TRUE;
    EW_Green := FALSE;
ELSE
    NS_Green := FALSE;
    EW_Green := TRUE;
END_IF
timer(IN := TRUE, PT := T#5s);
IF timer.Q THEN
    phase := 1 - phase;
    timer(IN := FALSE);
END_IF
